mapper.select:
SELECT EMAIL
  FROM MEMBER
 WHERE MEMBER_NAME = #{request.memberName}
   AND BIRTH_DATE = #{request.birthDate, jdbcType=DATE}
   AND REGEXP_REPLACE(PHONE_NUMBER, '[^0-9]', '') = #{request.phoneNumber}
   AND MEMBER_STATUS = 'ACTIVE'

SELECT MEMBER_ID
  FROM MEMBER
 WHERE LOWER(EMAIL) = #{request.email}
   AND BIRTH_DATE = #{request.birthDate, jdbcType=DATE}
   AND REGEXP_REPLACE(PHONE_NUMBER, '[^0-9]', '') = #{request.phoneNumber}
   AND MEMBER_STATUS = 'ACTIVE'
